import FluentKit
import Foundation

/// Where customers rows are kept. Services depend only on this protocol.
public protocol CustomerRepository: Sendable {
    /// The row with this primary key, or nil.
    func findById(_ id: Int) async throws -> Customer?

    /// At most limit rows from offset, by primary key, and how many there are.
    func list(offset: Int, limit: Int) async throws -> Page<Customer>

    /// The row with this email, or nil.
    func findByEmail(_ email: String) async throws -> Customer?

    /// Stores a new row; the values the database fills are read back.
    @discardableResult
    func insert(_ entity: Customer) async throws -> Customer

    /// Stores the changes made to a row.
    @discardableResult
    func update(_ entity: Customer) async throws -> Customer

    /// Removes a row.
    func delete(_ entity: Customer) async throws
}

/// Keeps customers rows in the database, through Fluent: on the database of the unit of work, or on its transaction.
public struct SqlCustomerRepository: CustomerRepository {
    let database: any Database

    public init(db: any Database) {
        self.database = db
    }

    public func findById(_ id: Int) async throws -> Customer? {
        try await CustomerModel.query(on: database).filter(\.$id == id).first().map(toEntity)
    }

    public func list(offset: Int, limit: Int) async throws -> Page<Customer> {
        let total = try await CustomerModel.query(on: database).count()
        let rows = try await CustomerModel.query(on: database).sort("id").offset(offset).limit(limit).all()
        return Page(items: rows.map(toEntity), total: total, offset: offset, limit: limit)
    }

    public func findByEmail(_ email: String) async throws -> Customer? {
        try await CustomerModel.query(on: database).filter(\.$email == email).first().map(toEntity)
    }

    @discardableResult
    public func insert(_ entity: Customer) async throws -> Customer {
        var values: [FieldKey: DatabaseQuery.Value] = [:]
        if let value = entity.email { values["email"] = .bind(value) }
        if let value = entity.fullName { values["full_name"] = .bind(value) }
        if let value = entity.status { values["status"] = .bind(value) }
        if let value = entity.createdAt { values["created_at"] = .bind(value) }
        if let value = entity.balanceCents { values["balance_cents"] = .bind(value) }
        if let value = entity.nickname { values["nickname"] = .bind(value) }
        if let value = entity.country { values["country"] = .bind(value) }
        let insert = CustomerModel.query(on: database).set(values)
        insert.query.action = .create
        nonisolated(unsafe) var numbered: Int?
        try await write { try await insert.run { numbered = try? $0.decode("id", as: Int.self) } }
        let stored = try await CustomerModel.query(on: database).filter(\.$id == numbered!).first()
        return stored.map(toEntity) ?? entity
    }

    @discardableResult
    public func update(_ entity: Customer) async throws -> Customer {
        let query = CustomerModel.query(on: database).filter(\.$id == entity.id!)
        if let value = entity.email { query.set(\.$email, to: value) }
        if let value = entity.fullName { query.set(\.$fullName, to: value) }
        if let value = entity.status { query.set(\.$status, to: value) }
        if let value = entity.createdAt { query.set(\.$createdAt, to: value) }
        if let value = entity.balanceCents { query.set(\.$balanceCents, to: value) }
        query.set(\.$nickname, to: entity.nickname)
        if let value = entity.country { query.set(\.$country, to: value) }
        try await write { try await query.update() }
        return entity
    }

    public func delete(_ entity: Customer) async throws {
        try await write { try await CustomerModel.query(on: database).filter(\.$id == entity.id!).delete() }
    }

    /// Runs a write; a database refusal (a unique value, a row still pointed to) becomes a conflict.
    private func write<T>(_ work: () async throws -> T) async throws -> T {
        do {
            return try await work()
        } catch let error as any DatabaseError where error.isConstraintFailure {
            throw DomainError.conflict(entity: "Customer", reason: "the database refused the change: \(error)", fields: [])
        }
    }
}

fileprivate func toEntity(_ model: CustomerModel) -> Customer {
    Customer(id: model.id, email: model.email, fullName: model.fullName, status: model.status, createdAt: model.createdAt, balanceCents: model.balanceCents, nickname: model.nickname, country: model.country)
}

/// Keeps customers rows in memory, for tests and for trying the services without a database.
public final class MemoryCustomerRepository: CustomerRepository {
    private let rows = MemoryRows<Customer>()

    public init() {}

    /// The rows reads see, by primary key.
    private func visible() async -> [Customer] {
        await rows.all.sorted(by: isBefore)
    }

    public func findById(_ id: Int) async throws -> Customer? {
        await visible().first { $0.id == id }
    }

    public func list(offset: Int, limit: Int) async throws -> Page<Customer> {
        let rows = await visible()
        return Page(items: Array(rows.dropFirst(offset).prefix(limit)), total: rows.count, offset: offset, limit: limit)
    }

    public func findByEmail(_ email: String) async throws -> Customer? {
        await visible().first { $0.email == email }
    }

    @discardableResult
    public func insert(_ entity: Customer) async throws -> Customer {
        var entity = entity
        if entity.id == nil { entity.id = await rows.nextId() }
        let row = entity
        await rows.store(row) { sameKey($0, row) }
        return row
    }

    @discardableResult
    public func update(_ entity: Customer) async throws -> Customer {
        await rows.store(entity) { sameKey($0, entity) }
        return entity
    }

    public func delete(_ entity: Customer) async throws {
        await rows.remove { sameKey($0, entity) }
    }
}

/// Whether two rows have the same key.
fileprivate func sameKey(_ a: Customer, _ b: Customer) -> Bool {
    a.id == b.id
}

/// Whether a row comes before another, by primary key.
fileprivate func isBefore(_ a: Customer, _ b: Customer) -> Bool {
    return less(a.id, b.id)
}

