import Foundation

/// Operations on customers. Each write runs in its own transaction.
public struct CustomerService: Sendable {
    private let unitOfWork: any UnitOfWork

    public init(unitOfWork: any UnitOfWork) {
        self.unitOfWork = unitOfWork
    }

    /// Stores a new Customer after checking it.
    @discardableResult
    public func createCustomer(_ data: CustomerCreate) async throws -> CustomerRead {
        let values = Values(email: data.email.map(Optional.some), fullName: data.fullName.map(Optional.some), status: data.status.map(Optional.some), createdAt: data.createdAt.map(Optional.some), balanceCents: data.balanceCents.map(Optional.some), nickname: data.nickname.map(Optional.some), country: data.country.map(Optional.some))
        return try await unitOfWork.transaction { uow in
            try await checkValues(uow, values, nil)
            var entity = Customer()
            applyValues(&entity, values)
            return try await read(uow.customers.insert(entity))
        }
    }

    /// The Customer with this key; notFound when there is none.
    public func getCustomer(_ id: Int) async throws -> CustomerRead {
        try await read(find(unitOfWork, id))
    }

    /// A page of customers, by primary key.
    public func listCustomers(offset: Int, limit: Int) async throws -> Page<CustomerRead> {
        try await unitOfWork.customers.list(offset: offset, limit: limit).map(read)
    }

    /// Changes the given values of a Customer.
    @discardableResult
    public func updateCustomer(_ id: Int, _ changes: CustomerUpdate) async throws -> CustomerRead {
        let values = given(changes)
        return try await unitOfWork.transaction { uow in
            var current = try await find(uow, id)
            try await checkValues(uow, values, current)
            applyValues(&current, values)
            return try await read(uow.customers.update(current))
        }
    }

    /// Deletes a Customer.
    public func deleteCustomer(_ id: Int) async throws {
        try await unitOfWork.transaction { uow in
            let current = try await find(uow, id)
            try await uow.customers.delete(current)
        }
    }

    /// The Customer with this email, or nil.
    public func findCustomerByEmail(_ email: String) async throws -> CustomerRead? {
        try await unitOfWork.customers.findByEmail(email).map(read)
    }
}

/// The values a create or an update gives, by field: nil when not given, .some(nil) when given empty.
fileprivate struct Values: Sendable {
    var email: String?? = nil
    var fullName: String?? = nil
    var status: String?? = nil
    var createdAt: Date?? = nil
    var balanceCents: Int?? = nil
    var nickname: String?? = nil
    var country: String?? = nil
}

/// Checks the values against the rules of the "customers" table, and the rows they point to; throws validationFailed with every problem.
fileprivate func validate(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    let creating = current == nil
    var errors: [FieldError] = []
    if let value = values.email ?? nil {
        if value.count > 120 {
            errors.append(FieldError("email", "is longer than 120 characters"))
        }
    } else if creating || values.email != nil {
        errors.append(FieldError("email", "is required"))
    }
    if let value = values.fullName ?? nil {
        if value.count > 120 {
            errors.append(FieldError("full_name", "is longer than 120 characters"))
        }
    } else if creating || values.fullName != nil {
        errors.append(FieldError("full_name", "is required"))
    }
    if let value = values.status ?? nil {
        if value.count > 10 {
            errors.append(FieldError("status", "is longer than 10 characters"))
        }
        if !["active", "blocked"].contains(value) {
            errors.append(FieldError("status", "must be one of: active, blocked"))
        }
    } else if creating || values.status != nil {
        errors.append(FieldError("status", "is required"))
    }
    if values.createdAt ?? nil == nil && (creating || values.createdAt != nil) {
        errors.append(FieldError("created_at", "is required"))
    }
    if values.balanceCents ?? nil == nil && (creating || values.balanceCents != nil) {
        errors.append(FieldError("balance_cents", "is required"))
    }
    if let value = values.nickname ?? nil {
        if value.count > 40 {
            errors.append(FieldError("nickname", "is longer than 40 characters"))
        }
    }
    if let value = values.country ?? nil {
        if value.count > 2 {
            errors.append(FieldError("country", "is longer than 2 characters"))
        }
    } else if creating || values.country != nil {
        errors.append(FieldError("country", "is required"))
    }
    if !errors.isEmpty { throw DomainError.validationFailed(entity: "Customer", errors: errors) }
}

/// Values that must be unique are not taken by another row.
fileprivate func checkUnique(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    if let email = values.email ?? current?.email,
       let other = try await uow.customers.findByEmail(email),
       current.map({ other.id != $0.id }) ?? true {
        throw DomainError.conflict(entity: "Customer", reason: "email is already taken", fields: ["email"])
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
fileprivate func checkValues(_ uow: any UnitOfWork, _ values: Values, _ current: Customer?) async throws {
    try await validate(uow, values, current)
    try await checkUnique(uow, values, current)
}

/// Sets the given values on the entity.
fileprivate func applyValues(_ entity: inout Customer, _ values: Values) {
    if let value = values.email { entity.email = value }
    if let value = values.fullName { entity.fullName = value }
    if let value = values.status { entity.status = value }
    if let value = values.createdAt { entity.createdAt = value }
    if let value = values.balanceCents { entity.balanceCents = value }
    if let value = values.nickname { entity.nickname = value }
    if let value = values.country { entity.country = value }
}

/// The values an update gives, by field.
fileprivate func given(_ changes: CustomerUpdate) -> Values {
    Values(email: changes.email.given, fullName: changes.fullName.given, status: changes.status.given, createdAt: changes.createdAt.given, balanceCents: changes.balanceCents.given, nickname: changes.nickname.given, country: changes.country.given)
}

/// The Customer with this key; notFound when there is none.
fileprivate func find(_ uow: any UnitOfWork, _ id: Int) async throws -> Customer {
    guard let row = try await uow.customers.findById(id) else {
        throw DomainError.notFound(entity: "Customer", key: "\(id)")
    }
    return row
}

/// The Customer as services return it.
fileprivate func read(_ entity: Customer) -> CustomerRead {
    CustomerRead(id: entity.id!, email: entity.email!, fullName: entity.fullName!, status: entity.status!, createdAt: entity.createdAt!, balanceCents: entity.balanceCents!, nickname: entity.nickname, country: entity.country!)
}

